:5px;background:#c9c3b4}.dot.done{background:var(--teal)}.fact{display:grid;grid-template-columns:42px 1fr;gap:14px;padding:18px 0;border-top:1px solid var(--line)}.fact b{font-size:19px}.fact p{margin:4px 0 0;font-size:16px}.number{font:30px/1.2 "Courier New",monospace;color:var(--red)}footer{margin-top:44px;border-top:1px solid var(--ink);padding-top:20px;font-size:14px}footer p{margin:7px 0}.success{background:var(--yellow);padding:18px;border:1px solid var(--ink)}[hidden]{display:none!important}
